import Combine
import Foundation
import simd
import UntoldEngine
import UntoldComponentKit
import UntoldJoltPhysics

// Scene construction runs on the main actor; runtime state belongs to the XR
// frame thread. Controls send lock-protected requests and read status snapshots.
final class GameScene: @unchecked Sendable {
    private let physics: JoltPhysicsBackend
    private let handTracking = GoalieHandTracking()
    private var palmEntities: [GoalieHandSide: EntityID] = [:]
    private var trackedHands: Set<GoalieHandSide> = []
    private var targetEntity: EntityID = .invalid
    private var requestedShot: PenaltySettings?
    private var statusText = "Ready for first penalty"
    private var countdown: (trajectory: PenaltyTrajectory, launchAt: TimeInterval)?
    private struct ActiveShot {
        var trajectory: PenaltyTrajectory
        var launchedAt: TimeInterval
        var firstBlock: GoalieHandSide?
    }
    private var activeShot: ActiveShot?
    private static let gravity = SIMD3<Float>(0, -9.8, 0)
    private var ballEntity: EntityID = .invalid
    private var floorEntity: EntityID = .invalid
    private var sunEntity: EntityID = .invalid
    private var contactSubscription: EventSubscription?
    private let requestLock = NSLock()
    private var resetRequested = false
    private var palmDropRequested = false
    private var observedFall = false
    private var observedFloorContact = false
    private var settledTime: Float = 0
    private var checkTime: Float = 0
    private var checkFinished = false

    private static let ballRadius: Float = 0.11
    private static let spawnPosition = SIMD3<Float>(0, 1.5, -3)
    private static let palmRadius: Float = 0.07
    private static let parkedPosition = SIMD3<Float>(0, -100, 0)

    /// Call before creating UntoldEngineXR: the backend choice locks on the
    /// first physics substep and persists across immersive-space reopenings.
    static func installPhysics() -> JoltPhysicsBackend? {
        var world = PhysicsWorldConfiguration()
        world.gravity = Self.gravity
        PhysicsCoordinator.shared.setWorldConfiguration(world)
        var settings = JoltWorldSettings()
        settings.continuousCollision = true
        settings.maxKinematicStep = 1.0
        settings.maxKinematicSpeed = 6.0
        guard let backend = registerJoltPhysics(settings: settings) else {
            Logger.log(message: "ImmersiveGol: Jolt registration failed")
            return nil
        }
        Logger.log(message: "ImmersiveGol: active physics backend = \(backend.id)")
        return backend
    }

    @MainActor
    init(physics: JoltPhysicsBackend) {
        self.physics = physics
        setupAssetPaths()
        configureEngineSystems()
        setupPhysicsCheck()
        setupPalms()
        let target = SphereNode(radius: 0.035, segments: [16, 12], name: "ImmersiveGol.shotTarget")
            .baseColor(0.8, 0.2, 1)
            .roughness(0.6)
        targetEntity = target.entityID
        translateTo(entityId: targetEntity, position: Self.parkedPosition)
        handTracking.start()
    }

    @MainActor
    private func configureEngineSystems() {
        gameMode = true
        ScenePluginSystem.discoverInApp()
        ScenePluginSystem.install()
        ScenePluginSystem.shared.startPlayMode()
        AnimationSystem.shared.isEnabled = true
        // M1 uses a fixed world-space floor. Spatial scene manipulation would
        // move the visuals independently of their static physics bodies.
    }

    @MainActor
    private func setupPhysicsCheck() {
        let floor = CubeNode(size: 1, name: "ImmersiveGol.floor")
            .baseColor(0.12, 0.35, 0.16)
            .roughness(0.9)
            .scaleTo(x: 32, y: 0.1, z: 32)
        floorEntity = floor.entityID
        // The top of the box is y = 0, matching the XR world floor.
        translateTo(entityId: floorEntity, position: SIMD3<Float>(0, -0.05, -3))
        registerComponent(entityId: floorEntity, componentType: ColliderComponent.self)
        registerComponent(entityId: floorEntity, componentType: RigidBodyComponent.self)
        if let collider = scene.get(component: ColliderComponent.self, for: floorEntity) {
            // Collider dimensions are explicit world metres, independent of visual scale.
            collider.shape = .box(halfExtents: SIMD3<Float>(16, 0.05, 16))
            collider.friction = 0.6
            collider.restitution = 0
        }
        scene.get(component: RigidBodyComponent.self, for: floorEntity)?.motionType = .static

        let ball = SphereNode(radius: Self.ballRadius, segments: [32, 24], name: "ImmersiveGol.ball")
            .baseColor(1, 0.9, 0.3)
            .roughness(0.7)
        ballEntity = ball.entityID
        translateTo(entityId: ballEntity, position: Self.spawnPosition)
        registerComponent(entityId: ballEntity, componentType: ColliderComponent.self)
        registerComponent(entityId: ballEntity, componentType: RigidBodyComponent.self)
        if let collider = scene.get(component: ColliderComponent.self, for: ballEntity) {
            collider.shape = .sphere(radius: Self.ballRadius)
            collider.friction = 0.5
            collider.restitution = 0.35
        }
        if let body = scene.get(component: RigidBodyComponent.self, for: ballEntity) {
            body.motionType = .dynamic
            body.mass = 0.43
            body.initialLinearVelocity = .zero
        }

        let sun = DirectionalLightNode(name: "ImmersiveGol.sun")
            .color(1, 0.98, 0.92)
            .intensity(2)
            .rotateBy(angle: -50, axis: [.x])
            .rotateBy(angle: 30, axis: [.y])
        sunEntity = sun.entityID

        contactSubscription = PhysicsEvents.shared.onContact { [weak self] event in
            guard let self, event.phase == .began else { return }
            if (event.entityA == self.ballEntity && event.entityB == self.floorEntity)
                || (event.entityB == self.ballEntity && event.entityA == self.floorEntity) {
                self.observedFloorContact = true
            }
            for (side, entity) in self.palmEntities {
                if (event.entityA == self.ballEntity && event.entityB == entity)
                    || (event.entityB == self.ballEntity && event.entityA == entity) {
                    Logger.log(message: "ImmersiveGol M2: ball blocked by \(side.rawValue) palm")
                    if self.activeShot != nil, self.activeShot?.firstBlock == nil {
                        self.activeShot?.firstBlock = side
                        self.setShotStatus("Palm contact: \(side.rawValue)")
                    }
                }
            }
        }
        Logger.log(message: "ImmersiveGol M1: dropping ball from 1.5 m, 3 m ahead")
    }

    func requestPhysicsReset() {
        requestLock.withLock { resetRequested = true }
    }

    func requestPalmDrop() {
        requestLock.withLock { palmDropRequested = true }
    }

    func requestPenalty(settings: PenaltySettings) {
        requestLock.withLock { requestedShot = settings.clamped }
    }

    var shotStatus: String {
        requestLock.withLock { statusText }
    }

    private func setShotStatus(_ text: String) {
        requestLock.withLock { statusText = text }
        Logger.log(message: "ImmersiveGol M3: \(text)")
    }

    private func cancelPenalty() {
        countdown = nil
        activeShot = nil
        translateTo(entityId: targetEntity, position: Self.parkedPosition)
    }

    private func updatePenalty(now: TimeInterval) {
        let settings = requestLock.withLock { () -> PenaltySettings? in
            defer { requestedShot = nil }
            return requestedShot
        }
        if let settings {
            var head = handTracking.headTransform(now: now)
            #if targetEnvironment(simulator)
            if head == nil {
                var fallback = matrix_identity_float4x4
                fallback.columns.3 = SIMD4<Float>(0, 1.65, 0, 1)
                head = fallback
            }
            #endif
            guard let head else {
                setShotStatus("Waiting for head tracking. Try Repeat Shot again.")
                return
            }
            let trajectory = PenaltyTrajectory(settings: settings, head: head, gravity: Self.gravity)
            guard physics.resetBody(entity: ballEntity, position: trajectory.origin, velocity: .zero) else {
                requestPenalty(settings: settings)
                return
            }
            cancelPenalty()
            checkFinished = true
            countdown = (trajectory, now + 3)
            translateTo(entityId: targetEntity, position: trajectory.target)
            setShotStatus("Shot in 3 — raise your hands")
        }
        if let pending = countdown {
            if now >= pending.launchAt {
                guard physics.resetBody(entity: ballEntity, position: pending.trajectory.origin,
                                        velocity: pending.trajectory.velocity) else { return }
                activeShot = ActiveShot(trajectory: pending.trajectory, launchedAt: now)
                countdown = nil
                setShotStatus("Ball launched — block the purple target")
            } else {
                let text = "Shot in \(Int(ceil(pending.launchAt - now))) — raise your hands"
                if shotStatus != text { setShotStatus(text) }
            }
        }
        guard let shot = activeShot, let state = physics.bodyState(for: ballEntity) else { return }
        // Whole ball beyond the captured keeper plane. M3 has no goal-mouth bounds yet.
        let passed = simd_dot(state.position - shot.trajectory.keeperPosition, shot.trajectory.forward)
            < -Self.ballRadius
        if passed {
            setShotStatus(shot.firstBlock.map { "Touched by \($0.rawValue) palm; passed goalie" }
                          ?? "Passed goalie — try again")
            activeShot = nil
        } else if now - shot.launchedAt > Double(shot.trajectory.flightTime) + 3 {
            setShotStatus(shot.firstBlock.map { "Deflected by \($0.rawValue) palm" }
                          ?? "Shot ended without palm contact")
            activeShot = nil
        }
    }

    @MainActor
    private func setupPalms() {
        for side in GoalieHandSide.allCases {
            // Visible collision proxies for M2 verification, replaced by gloves later.
            let color = side == .left ? SIMD3<Float>(0.15, 0.65, 1) : SIMD3<Float>(1, 0.35, 0.15)
            let node = SphereNode(radius: Self.palmRadius, segments: [16, 12],
                                  name: "ImmersiveGol.\(side.rawValue)Palm")
                .baseColor(color.x, color.y, color.z)
                .roughness(0.7)
            let entity = node.entityID
            palmEntities[side] = entity
            translateTo(entityId: entity, position: Self.parkedPosition)
            registerComponent(entityId: entity, componentType: ColliderComponent.self)
            registerComponent(entityId: entity, componentType: RigidBodyComponent.self)
            if let collider = scene.get(component: ColliderComponent.self, for: entity) {
                collider.shape = .sphere(radius: Self.palmRadius)
                collider.friction = 0.5
                collider.restitution = 0.2
            }
            scene.get(component: RigidBodyComponent.self, for: entity)?.motionType = .kinematic
        }
    }

    private func updatePalms() {
        let now = ProcessInfo.processInfo.systemUptime
        for side in GoalieHandSide.allCases {
            guard let entity = palmEntities[side] else { continue }
            let position = handTracking.palmPosition(side, now: now)
            // The coordinator forwards the transform as a Jolt kinematic target.
            // Parking is a >1 m jump, so maxKinematicStep makes it a teleport
            // with zero velocity rather than sweeping the hand through the ball.
            translateTo(entityId: entity, position: position ?? Self.parkedPosition)
            if position != nil {
                if trackedHands.insert(side).inserted {
                    Logger.log(message: "ImmersiveGol M2: \(side.rawValue) palm tracking acquired")
                }
            } else if trackedHands.remove(side) != nil {
                Logger.log(message: "ImmersiveGol M2: \(side.rawValue) palm tracking lost; collider parked")
            }
        }
    }

    func update(deltaTime: Float) {
        guard gameMode else { return }
        // Keep hands updating after the M1 drop check has completed.
        updatePalms()
        let shouldReset = requestLock.withLock { () -> Bool in
            defer { resetRequested = false }
            return resetRequested
        }
        if shouldReset {
            cancelPenalty()
            setShotStatus("M1 floor check")
            if physics.resetBody(entity: ballEntity, position: Self.spawnPosition, velocity: .zero) {
                observedFall = false
                observedFloorContact = false
                settledTime = 0
                checkTime = 0
                checkFinished = false
                Logger.log(message: "ImmersiveGol M1: repeating drop check")
            } else {
                requestPhysicsReset() // Coordinator has not created the body yet.
            }
        }
        let shouldDropAbovePalm = requestLock.withLock { () -> Bool in
            defer { palmDropRequested = false }
            return palmDropRequested
        }
        if shouldDropAbovePalm {
            cancelPenalty()
            setShotStatus("M2 palm drop check")
            let now = ProcessInfo.processInfo.systemUptime
            let palm = handTracking.palmPosition(.right, now: now)
                ?? handTracking.palmPosition(.left, now: now)
            if let palm {
                let position = palm + SIMD3<Float>(0, 0.4, 0)
                if physics.resetBody(entity: ballEntity, position: position, velocity: .zero) {
                    // Palm interactions are a separate check from M1's floor drop.
                    checkFinished = true
                    Logger.log(message: "ImmersiveGol M2: ball dropped above palm; hold your hand beneath it")
                } else {
                    requestPalmDrop()
                }
            } else {
                Logger.log(message: "ImmersiveGol M2: show a tracked palm before requesting a drop")
            }
        }
        updatePenalty(now: ProcessInfo.processInfo.systemUptime)
        guard !checkFinished, let state = physics.bodyState(for: ballEntity) else { return }
        checkTime += deltaTime
        if state.position.y < Self.spawnPosition.y - 0.1 && state.velocity.y < -0.1 {
            observedFall = true
        }
        let resting = abs(state.position.y - Self.ballRadius) < 0.02
            && simd_length(state.velocity) < 0.05
        settledTime = resting ? settledTime + deltaTime : 0
        if observedFall && observedFloorContact && settledTime >= 0.5 {
            checkFinished = true
            Logger.log(message: "ImmersiveGol M1 PASS: ball fell, hit floor, and settled at y=\(state.position.y)")
        } else if checkTime > 10 {
            checkFinished = true
            Logger.log(message: "ImmersiveGol M1 FAIL: fall=\(observedFall), contact=\(observedFloorContact), y=\(state.position.y), speed=\(simd_length(state.velocity))")
        }
    }

    func handleInput() {}

    /// Called on the frame thread after the renderer stops.
    func shutdown() {
        handTracking.stop()
        contactSubscription?.cancel()
        contactSubscription = nil
        for entity in [ballEntity, floorEntity, sunEntity, targetEntity] + Array(palmEntities.values) where entity != .invalid {
            destroyEntity(entityId: entity)
            // Remove now so reopening does not depend on another coordinator step.
            physics.didRemoveBody(entity: entity)
        }
        ballEntity = .invalid
        floorEntity = .invalid
        sunEntity = .invalid
        palmEntities.removeAll()
        trackedHands.removeAll()
    }
}

@MainActor
final class EngineStatsWindowStore: ObservableObject {
    static let shared = EngineStatsWindowStore()

    @Published var advancedMode: Bool = false
    @Published private(set) var compactText: String = ""
    @Published private(set) var expandedText: String = ""

    private var timer: Timer?

    private init() {
        refresh()
        timer = Timer.scheduledTimer(withTimeInterval: 0.25, repeats: true) { [weak self] _ in
            guard let self else { return }
            Task { @MainActor in
                self.refresh()
            }
        }
    }

    deinit {
        timer?.invalidate()
    }

    private func refresh() {
        let snapshot = getEngineStatsSnapshot()
        compactText = formatEngineStatsCompact(snapshot)
        expandedText = formatEngineStatsOverlay(snapshot)
    }
}
